from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.rows=[]; self.cur=None; self.capture=None
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        cls=a.get('class','')
        if tag=='div' and 'row' in cls.split():
            self.cur={'texts':[], 'sizes':[], 'file':False, 'folder':False}
        if tag=='i' and 'file outline icon' in cls:
            self.cur['file']=True
        if tag=='i' and 'folder icon' in cls:
            self.cur['folder']=True
        if tag=='div' and 'column' in cls.split():
            self.capture='text' if 'left floated' in cls or 'no-padding left' in cls else 'size' if 'right aligned' in cls else None
        self.stack.append((tag,cls,self.capture))
    def handle_data(self,data):
        if self.cur is not None:
            s=data.strip()
            if s:
                self.cur['texts'].append(s)
    def handle_endtag(self, tag):
        if tag=='div' and self.cur is not None:
            # when row closes? can't know easily
            pass
        if self.stack:
            self.stack.pop()
p=P(); p.feed(open('[REDACTED LOCAL PATH]').read())
# no close capture. print text containing h5
# let's simply regex better from raw
import re
txt=open('[REDACTED LOCAL PATH]').read()
# file entries are like <span><i class=\"file outline icon\"></i></i> NAME</span> ... <div class=\"no-padding right aligned column\">SIZE</div>
# split by row
for row in re.split(r'<div class=\"row\">', txt):
    if 'file outline icon' in row:
        name=re.search(r'<span>(.*?)</span>', row, re.S)
        size=re.search(r'right aligned column\">(.*?)</div>', row, re.S)
        n=name.group(1) if name else ''
        n=re.sub(r'<.*?>','',n)
        n=' '.join(n.split())
        s=size.group(1).strip() if size else ''
        if '.h5' in n or 'fold' in n:
            print(n, s)
PY"

